import { listVideoInputDevices } from "../pose/provider-wiring.js";

export function renderCameraSelector({ captureState = "idle", onStartCapture, onStopCapture, onDeviceChange }) {
  const container = document.createElement("div");
  container.className = "mf-camera-selector";
  container.style.display = "flex";
  container.style.flexDirection = "column";
  container.style.gap = "8px";

  const label = document.createElement("span");
  label.className = "mf-camera-label";
  label.style.fontSize = "12px";
  label.style.color = "#b9b9c4";
  label.style.textTransform = "uppercase";
  label.style.letterSpacing = "0.5px";
  label.textContent = "Câmera";
  container.appendChild(label);

  const row = document.createElement("div");
  row.className = "mf-camera-row";
  row.style.display = "flex";
  row.style.alignItems = "center";
  row.style.gap = "8px";

  // Device select
  const select = document.createElement("select");
  select.className = "mf-camera-select";
  select.style.flex = "1";
  select.style.appearance = "menulist";
  select.style.background = "#26262b";
  select.style.color = "#e7e7e7";
  select.style.border = "1px solid #444";
  select.style.borderRadius = "6px";
  select.style.padding = "6px 8px";
  select.style.fontSize = "13px";
  select.style.cursor = "pointer";

  const defaultOption = document.createElement("option");
  defaultOption.value = "";
  defaultOption.textContent = "Selecionar câmera…";
  select.appendChild(defaultOption);

  // Enumerate devices and populate
  listVideoInputDevices()
    .then((devices) => {
      devices.forEach((device) => {
        const opt = document.createElement("option");
        opt.value = device.deviceId;
        opt.textContent = device.labelUnknown
          ? `Câmera ${device.deviceId.slice(0, 8)}${device.deviceId.slice(8) ? "…" : ""} (sem nome)`
          : device.label;
        select.appendChild(opt);
      });
      const state = typeof captureState === "object" ? captureState : null;
    })
    .catch(() => {
      // keep selector usable even when enumeration fails
    });

  select.addEventListener("change", (event) => {
    const candidate = Array.from(select.options).find(
      (opt) => opt.value === event.target.value,
    );
    if (!candidate || candidate.value === "") return;
    const devices = Array.from(select.options).slice(1).map((opt) => ({
      deviceId: opt.value,
      label: opt.textContent,
      labelUnknown: opt.textContent.includes("(sem nome)"),
    }));
    const match = devices.find((d) => d.deviceId === event.target.value);
    if (match) {
      onDeviceChange?.(match.deviceId);
    }
  });

  const isRequesting = captureState === "requestingcamera";
  const isCapturing = captureState === "capturing";
  const isIdle = captureState === "idle";
  const ok = captureState === "camera-ready";

  select.disabled = isRequesting || isCapturing;
  row.appendChild(select);

  if (isIdle) {
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "mf-camera-btn";
    btn.style.padding = "6px 10px";
    btn.style.borderRadius = "6px";
    btn.style.border = "1px solid #444";
    btn.style.background = "#26262b";
    btn.style.color = "#e7e7e7";
    btn.style.cursor = "pointer";
    btn.textContent = "Abrir câmera";
    btn.addEventListener("click", onStartCapture);
    row.appendChild(btn);
  }

  if (isRequesting) {
    const status = document.createElement("span");
    status.className = "mf-camera-status";
    status.style.fontSize = "12px";
    status.style.color = "#f0888a";
    status.textContent = "solicitando câmera…";
    row.appendChild(status);
  }

  if (isCapturing) {
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "mf-camera-btn";
    btn.style.padding = "6px 10px";
    btn.style.borderRadius = "6px";
    btn.style.border = "1px solid #444";
    btn.style.background = "#26262b";
    btn.style.color = "#e7e7e7";
    btn.style.cursor = "pointer";
    btn.textContent = "Parar câmera";
    btn.addEventListener("click", onStopCapture);
    row.appendChild(btn);
  }

  if (ok) {
    const okStatus = document.createElement("span");
    okStatus.className = "mf-camera-ok";
    okStatus.style.fontSize = "12px";
    okStatus.style.color = "#7fe3b4";
    okStatus.textContent = "câmera ativa";
    row.appendChild(okStatus);
  }

  container.appendChild(row);
  return container;
}
